// Draws to both buffers to keep them in sync and prevent flicker
void draw_to_both(int x_start, int x_end, int y_start, int y_end, short int color) {
    volatile int *pixel_ctrl_ptr = (int *)FRAME_BASE;
    int back = *(pixel_ctrl_ptr + 1);
    int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;
    short int *other_cache = (other == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;
    short int *back_cache  = (back  == (int)&Buffer1) ? cursor_bg_buffer1 : cursor_bg_buffer2;

    // draw to back buffer (cursor is already erased here from top of loop)
    pixel_buffer_start = back;
    fill_area(x_start, x_end, y_start, y_end, color);

    // erase cursor on other buffer before drawing, so we don't cache cursor pixels
    pixel_buffer_start = other;
    erase_cursor(mouseX, mouseY, other_cache);
    fill_area(x_start, x_end, y_start, y_end, color);

    // re-cache background on both buffers at current mouse position
    pixel_buffer_start = back;
    cache_cursor_bg(mouseX, mouseY, back_cache);

    pixel_buffer_start = other;
    cache_cursor_bg(mouseX, mouseY, other_cache);

    // restore to back buffer
    pixel_buffer_start = back;
}

void plot_pixel_both(int x, int y, short int color) {
    volatile int *pixel_ctrl_ptr = (int *)FRAME_BASE;
    int back = *(pixel_ctrl_ptr + 1);
    int other = (back == (int)&Buffer1) ? (int)&Buffer2 : (int)&Buffer1;

    pixel_buffer_start = back;
    plot_pixel(x, y, color);

    pixel_buffer_start = other;
    plot_pixel(x, y, color);

    pixel_buffer_start = back;
}

void draw_sprite(int x, int y, int w, int h, const short int sprite[]) {
    for (int row = 0; row < h; row++) {
        for (int col = 0; col < w; col++) {
            short int color = sprite[row * w + col];
            // skip transparent pixels (use 0x0000 or a chosen key color as transparent)
            if (color != 0x0000)
                plot_pixel(x + col, y + row, color);
        }
    }
}

void draw_instrument_label(int type, int y) {
    switch (type) {
        case 1: draw_sprite(-2, y - 10, PIANO_ICON_SIZE, PIANO_ICON_SIZE, piano_sprite); break; // piano
        case 2: draw_sprite(-2, y - 10, VOCAL_ICON_SIZE, VOCAL_ICON_SIZE, vocal_sprite); break; // vocal
        case 3: draw_sprite(1, y - 8, HIHAT_ICON_SIZE, HIHAT_ICON_SIZE, hihat_sprite); break; // hihat
        case 4: draw_sprite(1, y - 8, SNARE_ICON_SIZE, SNARE_ICON_SIZE, snare_sprite); break; // snare
        case 5: draw_sprite(2, y - 7, BASS_ICON_SIZE, BASS_ICON_SIZE, bass_sprite); break; // bass
        default: return;
    }
}

//------------ TIMER FUNCTIONS -------------

double find_seconds_per_bar(int bpm) {
	return 60.0 /bpm;
}

void count_bars(int bpm, int bars, int continuous, int *stop) {
    // calculate total seconds for the bars
    double seconds = bars * find_seconds_per_bar(bpm);
    unsigned int counter_start_value = (unsigned int)(TIMER_FREQ * seconds);

    // stop timer first
    TIMER_CTRL = 0;

    // clear TO bit
    TIMER_STATUS = 0;

    // split 32-bit start value into low/high 16-bit registers
    int counter_low  = counter_start_value & 0xFFFF;
    int counter_high = (counter_start_value >> 16) & 0xFFFF;

    TIMER_LOW  = counter_low;
    TIMER_HIGH = counter_high;

    // control bits
    int begin = 0b100; // single-shot
    if (continuous == 1) {
        begin = 0b110; // start + continuous
    }

    // start timer
    TIMER_CTRL = begin;
	TIMER_STATUS = 0;
	
    if (continuous == 1) {
        // keep running until stop is set
        while (*stop == 0) {
            // poll TO bit
            if ((TIMER_STATUS & 0x1) != 0) {
                TIMER_STATUS = 0; // clear TO if counter is done
            }
        }
        TIMER_CTRL = 0; // stop timer
    } else {
        // single-shot: wait until done
        while ((TIMER_STATUS & 0x1) == 0);
        TIMER_STATUS = 0;
    }
}

//plays any audio given
void play_audio(const int audio_sample[], int num_of_samples) {
	for (int i = 0; i < num_of_samples; i++) {
		int space = 0;
		while (space == 0) {
			int left = (AUDIO_FIFOSPACE >> 24) & 0xFF;
			int right = (AUDIO_FIFOSPACE >> 16) & 0xFF;
			space = (left < right) ? left : right;
		}
		AUDIO_LEFT = audio_sample[i] * VOLUME_MULTIPLIER;
		AUDIO_RIGHT = audio_sample[i] * VOLUME_MULTIPLIER;
	}
}

//plots a pixel at any coordinate x, y
void plot_pixel(int x, int y, short int line_color) {
    volatile short int *one_pixel_address;
	one_pixel_address = (short int*)(pixel_buffer_start + (y << 10) + (x << 1));
	*one_pixel_address = line_color;
}

//gets the color of pixel at any coordinate x, y
short int get_pixel(int x, int y) {
    volatile short int *one_pixel_address;
    one_pixel_address = (short int*)(pixel_buffer_start + (y << 10) + (x << 1));
    return *one_pixel_address;  // read
}

